    def record_child_provenance(self, child: subprocess.Popen, identity: dict | None,
                                expected_argv: list[str], actual_bytes: bytes | None,
                                accepted: bool, stage: str) -> None:
        expected = [arg.encode() for arg in expected_argv]
        actual = actual_bytes.rstrip(b'\0').split(b'\0') if actual_bytes is not None else None
        self.child_provenance.append({
            'pid': child.pid, 'identity': identity, 'stage': stage, 'guard_accepted': accepted,
            'captured_only_by_original_child_guard': True,
            'actual_argc': len(actual) if actual is not None else None,
            'expected_argc': len(expected),
            'actual_cmdline_bytes': len(actual_bytes) if actual_bytes is not None else None,
            'actual_cmdline_sha256': hashlib.sha256(actual_bytes).hexdigest() if actual_bytes is not None else None,
            'args': [{'index': index, 'bytes': len(arg), 'sha256': hashlib.sha256(arg).hexdigest(),
                      'expected_bytes': len(expected[index]) if index < len(expected) else None,
                      'expected_sha256': hashlib.sha256(expected[index]).hexdigest() if index < len(expected) else None,
                      'equal': index < len(expected) and arg == expected[index]}
                     for index, arg in enumerate(actual[:32] if actual is not None else [])],
            'arg_projection_limit': 32,
            'extra_args_omitted': max(0, len(actual) - 32) if actual is not None else 0,
