            'controller_sha256': digest(Path(__file__)), 'work_root': str(ROOT), 'ports': list(PORTS),
            'loopback_only': True, 'case_labels': [x[0] for x in CASES],
            'http_seconds': HTTP_SECONDS, 'whole_phase_seconds': WHOLE_SECONDS,
