def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument('--prepare-only', action='store_true')
    args = parser.parse_args()
    prepared = prepare()
    if args.prepare_only:
        print(json.dumps(prepared, sort_keys=True), flush=True)
